use std::collections::BTreeMap;#[derive(Clone,Debug,PartialEq,Eq)]pub enum Type{Bool,I32,U32,U16,U8,String,Named(String)}#[derive(Debug)]pub struct Diagnostic{pub file:String,pub line:usize,pub column:usize,pub message:String}#[derive(Default)]pub struct Checker{symbols:BTreeMap<String,Type>,pub errors:Vec<Diagnostic>}impl Checker{pub fn declare(&mut self,f:&str,l:usize,n:&str,t:Type){if self.symbols.insert(n.into(),t).is_some(){self.errors.push(Diagnostic{file:f.into(),line:l,column:1,message:format!("duplicate `{n}`")})}}}
